      "path": "app/src/main.tsx",
      "folder": "app/src",
      "content": "import React from 'react';\nimport ReactDOM from 'react-dom/client';\nimport App from './app';\n\nconst rootElement = document.getElementById('root')!;\nconst root = ReactDOM.createRoot(rootElement);\nroot.render(<App />);\n",
