      "path": "app/src/useWatchUseFieldArrayNested.tsx",
      "folder": "app/src",
      "content": "import React from 'react';\nimport {\n  Controller,\n  useFieldArray,\n  useForm,\n  useWatch,\n  Control,\n} from 'react-hook-form';\n\ntype FormValues = {\n  test: {\n    firstName: string;\n    lastName: string;\n    keyValue: { name: string }[];\n  }[];\n};\n\nfunction NestedArray({\n  control,\n  index,\n}: {\n  control: Control<FormValues>;\n  index: number;\n}) {\n  const { fields, append, prepend, swap, move, remove, insert, update } =\n    useFieldArray<FormValues, 'test.0.keyValue'>({\n      name: `test.${index}.keyValue` as 'test.0.keyValue',\n      control,\n    });\n  const value = useWatch({\n    name: 'test',\n    control,\n  });\n  const renderCountRef = React.useRef(0);\n  renderCountRef.current++;\n\n  return (\n    <div>\n      <div>\n        {fields.map((item, i) => (\n          <Controller\n            key={item.id}\n            render={({ field }) => <input {...field} aria-label={'name'} />}\n            name={`test.${index}.keyValue.${i}.name`}\n            control={control}\n          />\n        ))}\n      </div>\n\n      <button\n        id={`nest-append-${index}`}\n        type=\"button\"\n        onClick={() => append({ name: 'append' })}\n      >\n        append\n      </button>\n\n      <button\n        id={`nest-prepend-${index}`}\n        type=\"button\"\n        onClick={() => prepend({ name: 'prepend' })}\n      >\n        prepend\n      </button>\n\n      <button\n        id={`nest-swap-${index}`}\n        onClick={() => swap(1, 2)}\n        type=\"button\"\n      >\n        swap\n      </button>\n\n      <button\n        id={`nest-move-${index}`}\n        onClick={() => move(2, 0)}\n        type=\"button\"\n      >\n        move\n      </button>\n\n      <button\n        id={`nest-insert-${index}`}\n        type=\"button\"\n        onClick={() => insert(1, { name: 'insert' })}\n      >\n        insert\n      </button>\n\n      <button\n        id={`nest-update-${index}`}\n        type=\"button\"\n        onClick={() => update(2, { name: 'update' })}\n      >\n        update\n      </button>\n\n      <button\n        id={`nest-remove-${index}`}\n        type=\"button\"\n        onClick={() => remove(1)}\n      >\n        remove\n      </button>\n\n      <button\n        id={`nest-remove-all-${index}`}\n        type=\"button\"\n        onClick={() => remove()}\n      >\n        remove all\n      </button>\n\n      <div id={`count-nest-${index}`}>{renderCountRef.current}</div>\n\n      {index === 0 && <p id=\"result\">{JSON.stringify(value)}</p>}\n    </div>\n  );\n}\n\nexport default () => {\n  const { register, control, reset, setValue, handleSubmit } =\n    useForm<FormValues>({\n      defaultValues: {\n        test: [\n          {\n            firstName: 'Bill',\n            lastName: 'Luo',\n            keyValue: [{ name: '1a' }, { name: '1c' }],\n          },\n        ],\n      },\n    });\n  const { fields, append, prepend, swap, move, insert, remove, update } =\n    useFieldArray({\n      control,\n      name: 'test',\n    });\n  const renderCountRef = React.useRef(0);\n  renderCountRef.current++;\n\n  return (\n    <form onSubmit={handleSubmit((e) => console.log(e))}>\n      {fields.map((item, index) => {\n        return (\n          <div key={item.id}>\n            <input\n              aria-label={`test.${index}.firstName`}\n              {...register(`test.${index}.firstName` as const)}\n            />\n            <NestedArray control={control} index={index} />\n          </div>\n        );\n      })}\n\n      <hr />\n\n      <button\n        id=\"append\"\n        type=\"button\"\n        onClick={() => append({ firstName: 'append' })}\n      >\n        append\n      </button>\n\n      <button\n        id=\"prepend\"\n        type=\"button\"\n        onClick={() => prepend({ firstName: 'prepend' })}\n      >\n        prepend\n      </button>\n\n      <button\n        id=\"update\"\n        type=\"button\"\n        onClick={() => update(1, { firstName: 'update' })}\n      >\n        update\n      </button>\n\n      <button id=\"swap\" onClick={() => swap(1, 2)} type=\"button\">\n        swap\n      </button>\n\n      <button id=\"move\" onClick={() => move(2, 0)} type=\"button\">\n        move\n      </button>\n\n      <button\n        id=\"insert\"\n        type=\"button\"\n        onClick={() => insert(1, { firstName: 'insert' })}\n      >\n        insert\n      </button>\n\n      <button id=\"remove\" type=\"button\" onClick={() => remove(1)}>\n        remove\n      </button>\n\n      <button id=\"removeAll\" type=\"button\" onClick={() => remove()}>\n        remove all\n      </button>\n\n      <button\n        id=\"setValue\"\n        type={'button'}\n        onClick={() =>\n          setValue('test', [\n            {\n              firstName: 'test',\n              lastName: 'test',\n              keyValue: [\n                {\n                  name: 'test',\n                },\n              ],\n            },\n            {\n              firstName: 'test1',\n              lastName: 'test1',\n              keyValue: [\n                {\n                  name: 'test1',\n                },\n              ],\n            },\n            {\n              firstName: 'test2',\n              lastName: 'test3',\n              keyValue: [\n                {\n                  name: 'test3',\n                },\n              ],\n            },\n          ])\n        }\n      >\n        setValue\n      </button>\n\n      <button\n        id=\"reset\"\n        type=\"button\"\n        onClick={() => {\n          reset({\n            test: [\n              { firstName: 'test' },\n              { firstName: 'test1' },\n              { firstName: 'test2' },\n            ],\n          });\n        }}\n      >\n        reset\n      </button>\n\n      <div id=\"count\">{renderCountRef.current}</div>\n\n      <button id={'submit'}>Submit</button>\n    </form>\n  );\n};\n",
