      "path": "e2e/conditionalField.spec.ts",
      "folder": "e2e",
      "content": "import { expect, test } from '@playwright/test';\n\nimport { type } from './utils';\n\ntest.describe('ConditionalField', () => {\n  test('should reflect correct form state and data collection', async ({\n    page,\n  }) => {\n    await page.goto('/conditionalField');\n\n    await expect\n      .poll(async () =>\n        JSON.parse((await page.locator('#state').textContent()) || 'null'),\n      )\n      .toEqual({\n        dirty: [],\n        isSubmitted: false,\n        submitCount: 0,\n        touched: [],\n        isDirty: false,\n        isSubmitting: false,\n        isSubmitSuccessful: false,\n        isValid: false,\n      });\n\n    await page.locator('select[name=\"selectNumber\"]').focus();\n    await page.locator('select[name=\"selectNumber\"]').selectOption('1');\n    await page.locator('select[name=\"selectNumber\"]').blur();\n    await type(page.locator('input[name=\"firstName\"]'), 'bill');\n    await type(page.locator('input[name=\"lastName\"]'), 'luo');\n    await page.locator('input[name=\"lastName\"]').blur();\n\n    await expect\n      .poll(async () =>\n        JSON.parse((await page.locator('#state').textContent()) || 'null'),\n      )\n      .toEqual({\n        dirty: ['selectNumber', 'firstName', 'lastName'],\n        isSubmitted: false,\n        submitCount: 0,\n        touched: ['selectNumber', 'firstName', 'lastName'],\n        isDirty: true,\n        isSubmitting: false,\n        isSubmitSuccessful: false,\n        isValid: true,\n      });\n    await page.locator('button#submit').click();\n    await expect(page.locator('#result').first()).toContainText(\n      '{\"selectNumber\":\"1\",\"firstName\":\"bill\",\"lastName\":\"luo\"}',\n    );\n    await expect\n      .poll(async () =>\n        JSON.parse((await page.locator('#state').textContent()) || 'null'),\n      )\n      .toEqual({\n        dirty: ['selectNumber', 'firstName', 'lastName'],\n        isSubmitted: true,\n        submitCount: 1,\n        touched: ['selectNumber', 'firstName', 'lastName'],\n        isDirty: true,\n        isSubmitting: false,\n        isSubmitSuccessful: true,\n        isValid: true,\n      });\n    await expect\n      .poll(async () =>\n        JSON.parse(\n          (await page.locator('#result').first().textContent()) || 'null',\n        ),\n      )\n      .toEqual({\n        selectNumber: '1',\n        firstName: 'bill',\n        lastName: 'luo',\n      });\n\n    await page.locator('select[name=\"selectNumber\"]').selectOption('2');\n    await expect\n      .poll(async () =>\n        JSON.parse((await page.locator('#state').textContent()) || 'null'),\n      )\n      .toEqual({\n        dirty: ['selectNumber', 'firstName', 'lastName'],\n        isSubmitted: true,\n        submitCount: 1,\n        touched: ['selectNumber', 'firstName', 'lastName'],\n        isDirty: true,\n        isSubmitting: false,\n        isSubmitSuccessful: true,\n        isValid: false,\n      });\n    await type(page.locator('input[name=\"min\"]'), '10');\n    await type(page.locator('input[name=\"max\"]'), '2');\n    await page.locator('input[name=\"max\"]').blur();\n    await expect\n      .poll(async () =>\n        JSON.parse((await page.locator('#state').textContent()) || 'null'),\n      )\n      .toEqual({\n        dirty: ['selectNumber', 'firstName', 'lastName', 'min', 'max'],\n        isSubmitted: true,\n        submitCount: 1,\n        touched: ['selectNumber', 'firstName', 'lastName', 'min', 'max'],\n        isDirty: true,\n        isSubmitting: false,\n        isSubmitSuccessful: true,\n        isValid: true,\n      });\n    await page.locator('button#submit').click();\n    await expect\n      .poll(async () =>\n        JSON.parse((await page.locator('#state').textContent()) || 'null'),\n      )\n      .toEqual({\n        dirty: ['selectNumber', 'firstName', 'lastName', 'min', 'max'],\n        isSubmitted: true,\n        submitCount: 2,\n        touched: ['selectNumber', 'firstName', 'lastName', 'min', 'max'],\n        isDirty: true,\n        isSubmitting: false,\n        isSubmitSuccessful: true,\n        isValid: true,\n      });\n    await expect\n      .poll(async () =>\n        JSON.parse(\n          (await page.locator('#result').first().textContent()) || 'null',\n        ),\n      )\n      .toEqual({\n        selectNumber: '2',\n        firstName: 'bill',\n        lastName: 'luo',\n        min: '10',\n        max: '2',\n      });\n\n    await page.locator('select[name=\"selectNumber\"]').selectOption('3');\n    await expect\n      .poll(async () =>\n        JSON.parse((await page.locator('#state').textContent()) || 'null'),\n      )\n      .toEqual({\n        dirty: ['selectNumber', 'firstName', 'lastName', 'min', 'max'],\n        isSubmitted: true,\n        submitCount: 2,\n        touched: ['selectNumber', 'firstName', 'lastName', 'min', 'max'],\n        isDirty: true,\n        isSubmitting: false,\n        isSubmitSuccessful: true,\n        isValid: true,\n      });\n\n    await type(page.locator('input[name=\"notRequired\"]'), 'test');\n    await page.locator('input[name=\"notRequired\"]').blur();\n    await expect\n      .poll(async () =>\n        JSON.parse((await page.locator('#state').textContent()) || 'null'),\n      )\n      .toEqual({\n        dirty: [\n          'selectNumber',\n          'firstName',\n          'lastName',\n          'min',\n          'max',\n          'notRequired',\n        ],\n        isSubmitted: true,\n        submitCount: 2,\n        touched: [\n          'selectNumber',\n          'firstName',\n          'lastName',\n          'min',\n          'max',\n          'notRequired',\n        ],\n        isDirty: true,\n        isSubmitting: false,\n        isSubmitSuccessful: true,\n        isValid: true,\n      });\n\n    await page.locator('button#submit').click();\n    await expect\n      .poll(async () =>\n        JSON.parse(\n          (await page.locator('#result').first().textContent()) || 'null',\n        ),\n      )\n      .toEqual({\n        selectNumber: '3',\n        firstName: 'bill',\n        lastName: 'luo',\n        min: '10',\n        max: '2',\n        notRequired: 'test',\n      });\n\n    await expect(page.locator('#renderCount')).toContainText('28');\n  });\n});\n",
