      "path": "examples/V6/conditionalFields.tsx",
      "folder": "examples/V6",
      "content": "import React from 'react';\nimport ReactDOM from 'react-dom';\nimport { useForm } from 'react-hook-form';\n\nexport default function App() {\n  const { register, watch, handleSubmit } = useForm();\n  const onSubmit = (data) => {\n    alert(JSON.stringify(data));\n  };\n\n  const moreDetail = watch('moreDetail');\n\n  return (\n    <div className=\"App\">\n      <form onSubmit={handleSubmit(onSubmit)}>\n        <div>\n          <label htmlFor=\"firstName\">First Name</label>\n          <input name=\"firstName\" placeholder=\"Bill\" ref={register} />\n        </div>\n\n        <div>\n          <label htmlFor=\"lastName\">Last Name</label>\n          <input name=\"lastName\" placeholder=\"Luo\" ref={register} />\n        </div>\n\n        <div>\n          <label htmlFor=\"email\">Email</label>\n          <input\n            name=\"email\"\n            placeholder=\"bluebill1049@hotmail.com\"\n            type=\"email\"\n            ref={register}\n          />\n        </div>\n\n        <div>\n          <label htmlFor=\"lastName\">More Details</label>\n          <input name=\"moreDetail\" type=\"checkbox\" ref={register} />\n        </div>\n\n        {moreDetail && (\n          <div>\n            <label>Interests</label>\n            <input type=\"text\" name=\"Interests\" ref={register} />\n          </div>\n        )}\n        <button type=\"submit\">Submit</button>\n      </form>\n    </div>\n  );\n}\n",
      "contentHash": "8f223b0ecc5f1edbeff846a4afa422e487eed98ea924db49ece8ba95ab178ed5",
      "lineCount": 52,
