      "path": "examples/V6/validationSchema.tsx",
      "folder": "examples/V6",
      "content": "import React from 'react';\nimport ReactDOM from 'react-dom';\nimport { useForm } from 'react-hook-form';\nimport * as yup from 'yup'; // you will have to install yup\n\nconst SignupSchema = yup.object().shape({\n  firstName: yup.string().required(),\n  age: yup.number().required().positive().integer(),\n  website: yup.string().url(),\n});\n\nexport default function App() {\n  const { register, handleSubmit, errors } = useForm({\n    validationSchema: SignupSchema,\n  });\n  const onSubmit = (data) => {\n    alert(JSON.stringify(data));\n  };\n\n  return (\n    <form onSubmit={handleSubmit(onSubmit)}>\n      <div>\n        <label>Develop?</label>\n        Yes\n        <input type=\"radio\" name=\"test\" value=\"yes\" ref={register} />\n        No\n        <input type=\"radio\" name=\"test\" value=\"no\" ref={register} />\n      </div>\n      <div>\n        <label>First Name</label>\n        <input type=\"text\" name=\"firstName\" ref={register} />\n      </div>\n      <div>\n        <label>Last Name</label>\n        <input type=\"text\" name=\"lastName\" ref={register} />\n      </div>\n      <div>\n        <label>Age</label>\n        <input type=\"text\" name=\"age\" ref={register} />\n      </div>\n      <div>\n        <label>Website</label>\n        <input type=\"text\" name=\"website\" ref={register} />\n      </div>\n\n      <div style={{ color: 'red' }}>\n        <pre>\n          {Object.keys(errors).length > 0 && (\n            <label>Errors: {JSON.stringify(errors, null, 2)}</label>\n          )}\n        </pre>\n      </div>\n      <input type=\"submit\" />\n    </form>\n  );\n}\n",
      "contentHash": "a3cd6e96a07942247a4c40065e3433a307d81804fbf664ae307cdae635d8ef59",
      "lineCount": 57,
      "moduleKind": "esm",
