      "path": "scripts/jest/jest.config.js",
      "folder": "scripts/jest",
      "content": "const jestDefaultConfig = {\n  clearMocks: true,\n  resetMocks: true,\n  restoreMocks: true,\n  rootDir: '.',\n  roots: ['<rootDir>/src'],\n  transformIgnorePatterns: ['[/\\\\\\\\]node_modules[/\\\\\\\\].+\\\\.(js|jsx)$'],\n};\n\nconst web = {\n  ...jestDefaultConfig,\n  displayName: {\n    name: 'Web',\n    color: 'cyan',\n  },\n  testMatch: ['**/__tests__/**/*.(spec|test).ts?(x)'],\n  transform: {\n    '^.+\\\\.tsx?$': '@swc/jest',\n  },\n  setupFilesAfterEnv: ['<rootDir>/scripts/jest/setup.ts'],\n  testEnvironment: 'jest-fixed-jsdom',\n  testEnvironmentOptions: {\n    customExportConditions: [''],\n  },\n};\n\nconst server = {\n  ...jestDefaultConfig,\n  displayName: {\n    name: 'Server',\n    color: 'blue',\n  },\n  testMatch: ['**/+([a-zA-Z]).server.(spec|test).ts?(x)'],\n  transform: {\n    '^.+\\\\.tsx?$': '@swc/jest',\n  },\n  testEnvironment: 'node',\n};\n\nconst getProjects = () => {\n  const testEnv = process.env.TEST_ENV;\n  if (!testEnv) {\n    return [web, server];\n  }\n\n  switch (testEnv) {\n    case 'web':\n      return [web];\n    case 'server':\n      return [server];\n  }\n};\n\nmodule.exports = {\n  collectCoverageFrom: [\n    '**/**/*.{ts,tsx}',\n    '!**/**/*.test.{ts,tsx}',\n    '!**/src/types/**',\n    '!**/node_modules/**',\n    '!**/dist/**',\n    '!**/__tests__/**',\n  ],\n  projects: getProjects(),\n};\n",
