      "path": "src/__tests__/logic/getFieldValue.test.ts",
      "folder": "src/__tests__/logic",
      "content": "import getFieldValue from '../../logic/getFieldValue';\nimport type { Field } from '../../types';\n\njest.mock('../../logic/getRadioValue', () => ({\n  __esModule: true,\n  default: () => ({\n    value: 2,\n  }),\n}));\n\njest.mock('../../logic/getCheckboxValue', () => ({\n  __esModule: true,\n  default: () => ({\n    value: 'testValue',\n  }),\n}));\n\ndescribe('getFieldValue', () => {\n  it('should return correct value when type is radio', () => {\n    expect(\n      getFieldValue({\n        name: 'test',\n        ref: {\n          type: 'radio',\n          name: 'test',\n        },\n      }),\n    ).toBe(2);\n  });\n\n  it('should return the correct value when type is checkbox', () => {\n    expect(\n      getFieldValue({\n        name: 'test',\n        ref: {\n          name: 'test',\n          type: 'checkbox',\n        },\n      }),\n    ).toBe('testValue');\n  });\n\n  it('should return it value for other types', () => {\n    expect(\n      getFieldValue({\n        name: 'test',\n        ref: {\n          type: 'text',\n          name: 'bill',\n          value: 'value',\n        },\n      }),\n    ).toBe('value');\n  });\n\n  it('should return empty string when radio input value is not found', () => {\n    expect(getFieldValue({ ref: {} } as Field['_f'])).toEqual(undefined);\n  });\n\n  it('should return files for input type file', () => {\n    expect(\n      getFieldValue({\n        name: 'test',\n        ref: {\n          type: 'file',\n          name: 'test',\n          files: null,\n        },\n      }),\n    ).toEqual(null);\n  });\n\n  it('should return undefined when input is not found', () => {\n    expect(\n      getFieldValue({\n        name: 'test',\n        ref: {\n          name: 'file',\n          files: null,\n        },\n      }),\n    ).toEqual(undefined);\n  });\n});\n",
