      "folder": "src/__tests__/logic",
      "content": "import getRadioValue from '../../logic/getRadioValue';\n\ndescribe('getRadioValue', () => {\n  it('should return default value if not valid or empty options', () => {\n    expect(getRadioValue(undefined)).toEqual({\n      isValid: false,\n      value: null,\n    });\n  });\n\n  it('should return valid to true when value found', () => {\n    expect(\n      getRadioValue([\n        { name: 'bill', checked: false, value: '1' } as HTMLInputElement,\n        { name: 'bill', checked: true, value: '2' } as HTMLInputElement,\n      ]),\n    ).toEqual({\n      isValid: true,\n      value: '2',\n    });\n  });\n\n  it('should return disabled input correctly', () => {\n    expect(\n      getRadioValue([\n        {\n          name: 'bill',\n          checked: false,\n          value: '1',\n          disabled: true,\n        } as HTMLInputElement,\n        { name: 'bill', checked: true, value: '2' } as HTMLInputElement,\n      ]),\n    ).toEqual({\n      isValid: true,\n      value: '2',\n    });\n\n    expect(\n      getRadioValue([\n        {\n          name: 'bill',\n          checked: false,\n          value: '1',\n        } as HTMLInputElement,\n        {\n          name: 'bill',\n          checked: true,\n          disabled: true,\n          value: '2',\n        } as HTMLInputElement,\n      ]),\n    ).toEqual({\n      isValid: false,\n      value: null,\n    });\n  });\n});\n",
