      "path": "src/__tests__/logic/getResolverOptions.test.ts",
      "folder": "src/__tests__/logic",
      "content": "import type { InternalFieldName } from '../..';\nimport getResolverOptions from '../../logic/getResolverOptions';\n\ndescribe('getFielfs', () => {\n  it('should return fields from `fieldsNames` and `fieldsRef`', () => {\n    const fieldNames: Set<InternalFieldName> = new Set(['test.sub', 'test1']);\n    const fieldsRef: any = {\n      test: {\n        sub: {\n          _f: {\n            ref: { name: 'test.sub', value: 'test' },\n            name: 'test.sub',\n            value: 'test',\n          },\n        },\n      },\n      test1: {\n        _f: {\n          ref: { name: 'test1', value: 'test1' },\n          name: 'test1',\n          value: 'test1',\n        },\n      },\n    };\n\n    expect(getResolverOptions(fieldNames, fieldsRef, undefined, true))\n      .toMatchInlineSnapshot(`\n      {\n        \"criteriaMode\": undefined,\n        \"fields\": {\n          \"test\": {\n            \"sub\": {\n              \"name\": \"test.sub\",\n              \"ref\": {\n                \"name\": \"test.sub\",\n                \"value\": \"test\",\n              },\n              \"value\": \"test\",\n            },\n          },\n          \"test1\": {\n            \"name\": \"test1\",\n            \"ref\": {\n              \"name\": \"test1\",\n              \"value\": \"test1\",\n            },\n            \"value\": \"test1\",\n          },\n        },\n        \"names\": [\n          \"test.sub\",\n          \"test1\",\n        ],\n        \"shouldUseNativeValidation\": true,\n      }\n    `);\n  });\n});\n",
