      "folder": "src/__tests__/logic",
      "content": "import getValidateError from '../../logic/getValidateError';\nimport noop from '../../utils/noop';\n\ndescribe('getValidateError', () => {\n  it('should return field error in correct format', () => {\n    expect(\n      getValidateError(\n        'This is a required field',\n        {\n          name: 'test1',\n          value: '',\n        },\n        'required',\n      ),\n    ).toEqual({\n      type: 'required',\n      message: 'This is a required field',\n      ref: {\n        name: 'test1',\n        value: '',\n      },\n    });\n\n    expect(\n      getValidateError(\n        false,\n        {\n          name: 'test1',\n          value: '',\n        },\n        'required',\n      ),\n    ).toEqual({\n      type: 'required',\n      message: '',\n      ref: {\n        name: 'test1',\n        value: '',\n      },\n    });\n  });\n\n  it('should return undefined when called with non string result', () => {\n    expect(getValidateError(undefined, noop)).toBeUndefined();\n  });\n});\n",
