      "folder": "src/__tests__/logic",
      "content": "import { VALIDATION_MODE } from '../../constants';\nimport getValidationModes from '../../logic/getValidationModes';\n\ndescribe('getValidationModes', () => {\n  it('shold return correct flags for each mode', () => {\n    expect(getValidationModes(VALIDATION_MODE.onBlur)).toEqual({\n      isOnSubmit: false,\n      isOnBlur: true,\n      isOnChange: false,\n      isOnAll: false,\n      isOnTouch: false,\n    });\n\n    expect(getValidationModes(VALIDATION_MODE.onChange)).toEqual({\n      isOnSubmit: false,\n      isOnBlur: false,\n      isOnChange: true,\n      isOnAll: false,\n      isOnTouch: false,\n    });\n\n    expect(getValidationModes(VALIDATION_MODE.onSubmit)).toEqual({\n      isOnSubmit: true,\n      isOnBlur: false,\n      isOnChange: false,\n      isOnAll: false,\n      isOnTouch: false,\n    });\n\n    expect(getValidationModes(undefined)).toEqual({\n      isOnSubmit: true,\n      isOnBlur: false,\n      isOnChange: false,\n      isOnAll: false,\n      isOnTouch: false,\n    });\n\n    expect(getValidationModes(VALIDATION_MODE.all)).toEqual({\n      isOnSubmit: false,\n      isOnBlur: false,\n      isOnChange: false,\n      isOnAll: true,\n      isOnTouch: false,\n    });\n\n    expect(getValidationModes(VALIDATION_MODE.onTouched)).toEqual({\n      isOnSubmit: false,\n      isOnBlur: false,\n      isOnChange: false,\n      isOnAll: false,\n      isOnTouch: true,\n    });\n  });\n});\n",
