      "path": "src/__tests__/logic/isWatched.test.ts",
      "folder": "src/__tests__/logic",
      "content": "import isWatched from '../../logic/isWatched';\n\ndescribe('isWatched', () => {\n  it('should return watched fields', () => {\n    expect(\n      isWatched('', {\n        registerName: new Set(),\n        mount: new Set(),\n        disabled: new Set(),\n        unMount: new Set(),\n        array: new Set(),\n        watch: new Set(),\n        focus: '',\n        watchAll: true,\n      }),\n    ).toBeTruthy();\n\n    expect(\n      isWatched('test', {\n        registerName: new Set(),\n        mount: new Set(),\n        disabled: new Set(),\n        unMount: new Set(),\n        array: new Set(),\n        watch: new Set(['test']),\n        focus: '',\n        watchAll: false,\n      }),\n    ).toBeTruthy();\n  });\n\n  it('should return true when watched with parent node', () => {\n    expect(\n      isWatched('test.test', {\n        registerName: new Set(),\n        mount: new Set(),\n        disabled: new Set(),\n        unMount: new Set(),\n        array: new Set(),\n        watch: new Set(['test']),\n        focus: '',\n        watchAll: false,\n      }),\n    ).toBeTruthy();\n\n    expect(\n      isWatched('test.test.test', {\n        registerName: new Set(),\n        mount: new Set(),\n        disabled: new Set(),\n        unMount: new Set(),\n        array: new Set(),\n        watch: new Set(['test.test']),\n        focus: '',\n        watchAll: false,\n      }),\n    ).toBeTruthy();\n\n    expect(\n      isWatched('test.test.test', {\n        registerName: new Set(),\n        mount: new Set(),\n        disabled: new Set(),\n        unMount: new Set(),\n        array: new Set(),\n        watch: new Set(['testFail.test', 'test.test']),\n        focus: '',\n        watchAll: false,\n      }),\n    ).toBeTruthy();\n\n    expect(\n      isWatched('test.0', {\n        registerName: new Set(),\n        mount: new Set(),\n        disabled: new Set(),\n        unMount: new Set(),\n        array: new Set(),\n        watch: new Set(['test']),\n        focus: '',\n        watchAll: false,\n      }),\n    ).toBeTruthy();\n\n    expect(\n      isWatched('test.0.test', {\n        registerName: new Set(),\n        mount: new Set(),\n        disabled: new Set(),\n        unMount: new Set(),\n        array: new Set(),\n        watch: new Set(['test.0']),\n        focus: '',\n        watchAll: false,\n      }),\n    ).toBeTruthy();\n  });\n\n  it(\"should return false when watched with parent node that doesn't match child name\", () => {\n    expect(\n      isWatched('test.test.test', {\n        registerName: new Set(),\n        mount: new Set(),\n        disabled: new Set(),\n        unMount: new Set(),\n        array: new Set(),\n        watch: new Set(['tesk.test']),\n        focus: '',\n        watchAll: false,\n      }),\n    ).toBeFalsy();\n\n    expect(\n      isWatched('test.test.test', {\n        mount: new Set(),\n        disabled: new Set(),\n        unMount: new Set(),\n        array: new Set(),\n        registerName: new Set(),\n        watch: new Set(['testFail.test']),\n        focus: '',\n        watchAll: false,\n      }),\n    ).toBeFalsy();\n  });\n\n  it('returns true on first prefix match without iterating the full Set', () => {\n    const watch = new Set(['a', 'b', 'c', 'd', 'e']);\n\n    expect(\n      isWatched('a.child', {\n        registerName: new Set(),\n        mount: new Set(),\n        disabled: new Set(),\n        unMount: new Set(),\n        array: new Set(),\n        watch,\n        focus: '',\n        watchAll: false,\n      }),\n    ).toBeTruthy();\n\n    expect(\n      isWatched('e.child', {\n        registerName: new Set(),\n        mount: new Set(),\n        disabled: new Set(),\n        unMount: new Set(),\n        array: new Set(),\n        watch,\n        focus: '',\n        watchAll: false,\n      }),\n    ).toBeTruthy();\n\n    expect(\n      isWatched('z.child', {\n        registerName: new Set(),\n        mount: new Set(),\n        disabled: new Set(),\n        unMount: new Set(),\n        array: new Set(),\n        watch,\n        focus: '',\n        watchAll: false,\n      }),\n    ).toBeFalsy();\n  });\n\n  it('should return falsy for blur event', () => {\n    expect(\n      isWatched(\n        '',\n        {\n          mount: new Set(),\n          disabled: new Set(),\n          registerName: new Set(),\n          unMount: new Set(),\n          array: new Set(),\n          watch: new Set(),\n          focus: '',\n          watchAll: true,\n        },\n        true,\n      ),\n    ).toBeFalsy();\n  });\n});\n",
      "contentHash": "9dd1ef4c0976e57f4437203bfd2740b1c8ec2ea6d7015e22735c6a22975ef5f8",
