      "path": "src/__tests__/logic/iterateFieldsByAction.test.ts",
      "folder": "src/__tests__/logic",
      "content": "import iterateFieldsByAction from '../../logic/iterateFieldsByAction';\n\ndescribe('iterateFieldsByAction', () => {\n  it('should focus on the first error it encounter', () => {\n    const focus = jest.fn();\n    iterateFieldsByAction(\n      {\n        test: {\n          _f: {\n            name: 'test',\n            ref: {\n              name: 'test',\n              focus,\n            },\n          },\n        },\n      },\n      (ref) => {\n        ref.focus && ref.focus();\n        return 1;\n      },\n    );\n\n    expect(focus).toHaveBeenCalled();\n  });\n\n  it('should focus on first option when options input error encounters', () => {\n    const focus = jest.fn();\n    iterateFieldsByAction(\n      {\n        test: {\n          _f: {\n            name: 'test',\n            ref: {\n              name: 'test',\n            },\n            refs: [\n              {\n                focus,\n              } as unknown as HTMLInputElement,\n            ],\n          },\n        },\n      },\n      (ref) => {\n        ref.focus && ref.focus();\n        return 1;\n      },\n    );\n\n    expect(focus).toHaveBeenCalled();\n  });\n\n  it('should not call focus when field is undefined', () => {\n    expect(() => {\n      iterateFieldsByAction(\n        {\n          test: undefined,\n        },\n        (ref) => {\n          ref.focus && ref.focus();\n          return 1;\n        },\n      );\n    }).not.toThrow();\n  });\n\n  it('should focus on the first error it encounter and not the second', () => {\n    const focus = jest.fn();\n    iterateFieldsByAction(\n      {\n        first: {\n          _f: {\n            name: 'first',\n            ref: {\n              name: 'first',\n              focus,\n            },\n          },\n        },\n        second: {\n          _f: {\n            name: 'second',\n            ref: {\n              name: 'second',\n              focus,\n            },\n          },\n        },\n      },\n      (ref) => {\n        // @ts-expect-error we want to test with what focus was called\n        ref.focus && ref.focus(ref.name);\n        return 1;\n      },\n    );\n    expect(focus).toHaveBeenCalledWith('first');\n    expect(focus).not.toHaveBeenCalledWith('second');\n  });\n\n  it('should recursively drill into objects', () => {\n    const focus = jest.fn();\n    iterateFieldsByAction(\n      {\n        test: {\n          name: {\n            first: {\n              _f: {\n                name: 'name.first',\n                ref: {\n                  name: 'first',\n                  focus,\n                },\n              },\n            },\n            last: {\n              _f: {\n                name: 'name.last',\n                ref: {\n                  name: 'last',\n                  focus,\n                },\n              },\n            },\n          },\n        },\n      },\n      (ref, key) => {\n        if (key === 'name.last') {\n          // @ts-expect-error we want to test with what focus was called\n          ref.focus && ref.focus(ref.name);\n          return 1;\n        }\n        return;\n      },\n    );\n    expect(focus).not.toHaveBeenCalledWith('first');\n    expect(focus).toHaveBeenCalledWith('last');\n  });\n\n  it('should recursively drill into objects and break out of all loops on first focus', () => {\n    const focus = jest.fn();\n    const notFocus = jest.fn();\n    iterateFieldsByAction(\n      {\n        personal: {\n          name: {\n            first: {\n              _f: {\n                name: 'name.first',\n                ref: {\n                  name: 'first',\n                  focus: notFocus,\n                },\n              },\n            },\n            last: {\n              _f: {\n                name: 'name.last',\n                ref: {\n                  name: 'last',\n                  focus,\n                },\n              },\n            },\n          },\n          phone: {\n            _f: {\n              name: 'phone',\n              ref: {\n                name: 'phone',\n                focus: notFocus,\n              },\n            },\n          },\n          address: {\n            line1: {\n              _f: {\n                name: 'address.line1',\n                ref: {\n                  name: 'line1',\n                  focus: notFocus,\n                },\n              },\n            },\n          },\n        },\n      },\n      (ref, key) => {\n        // @ts-expect-error we want to test with what focus was called\n        ref.focus && ref.focus(ref.name);\n        return key === 'name.last' ? 1 : undefined;\n      },\n    );\n    // 'focus' should be called on 'last' and never again\n    expect(focus).not.toHaveBeenCalledWith('first'); // not valid\n    expect(focus).toHaveBeenCalledWith('last'); // valid\n    expect(focus).not.toHaveBeenCalledWith('phone'); // stopped\n    expect(focus).not.toHaveBeenCalledWith('line1');\n    // 'notFocus' should be called on the first, then never again\n    expect(notFocus).toHaveBeenCalledWith('first'); // not valid\n    expect(notFocus).not.toHaveBeenCalledWith('last'); // valid\n    expect(notFocus).not.toHaveBeenCalledWith('phone'); // stopped\n    expect(notFocus).not.toHaveBeenCalledWith('line1');\n  });\n\n  it('should break out of all loops when the match is nested below a sibling top-level group', () => {\n    const focus = jest.fn();\n    const notFocus = jest.fn();\n    iterateFieldsByAction(\n      {\n        personal: {\n          name: {\n            last: {\n              _f: {\n                name: 'name.last',\n                ref: {\n                  name: 'last',\n                  focus,\n                },\n              },\n            },\n          },\n        },\n        work: {\n          email: {\n            _f: {\n              name: 'work.email',\n              ref: {\n                name: 'email',\n                focus: notFocus,\n              },\n            },\n          },\n        },\n      },\n      (ref, key) => {\n        // @ts-expect-error we want to test with what focus was called\n        ref.focus && ref.focus(ref.name);\n        return key === 'name.last' ? 1 : undefined;\n      },\n    );\n    expect(focus).toHaveBeenCalledWith('last');\n    expect(notFocus).not.toHaveBeenCalled();\n  });\n});\n",
      "contentHash": "8b73c7500ee4a12ccb89d2e7978cf14f8d88ee7d9fb87c5b346f78b42e487053",
      "lineCount": 247,
      "moduleKind": "esm",
