      "path": "src/__tests__/logic/schemaErrorLookup.test.ts",
      "folder": "src/__tests__/logic",
      "content": "import schemaErrorLookup from '../../logic/schemaErrorLookup';\n\ndescribe('errorsLookup', () => {\n  it('should be able to look up the error', () => {\n    expect(\n      schemaErrorLookup<{\n        test: {\n          deep: string;\n        };\n      }>(\n        {\n          test: {\n            type: 'test',\n            message: 'error',\n            deep: {\n              type: 'deep',\n              message: 'error',\n            },\n          },\n        },\n        {},\n        'test.deep.whatever',\n      ),\n    ).toEqual({\n      error: {\n        type: 'deep',\n        message: 'error',\n      },\n      name: 'test.deep',\n    });\n\n    expect(\n      schemaErrorLookup(\n        {\n          test: {\n            type: 'test',\n            message: 'error',\n          },\n        },\n        {},\n        'test.0.whatever',\n      ),\n    ).toEqual({\n      error: {\n        type: 'test',\n        message: 'error',\n      },\n      name: 'test',\n    });\n\n    expect(\n      schemaErrorLookup(\n        {\n          test: {\n            type: 'test',\n            message: 'error',\n          },\n        },\n        {},\n        'test',\n      ),\n    ).toEqual({\n      error: {\n        type: 'test',\n        message: 'error',\n      },\n      name: 'test',\n    });\n\n    expect(\n      schemaErrorLookup<{\n        test: {\n          deep: string;\n        };\n        test1: {\n          nested: {\n            deepNested: string;\n          };\n        };\n      }>(\n        {\n          test: {\n            type: 'test',\n            message: 'error',\n          },\n          test1: {\n            type: 'test',\n            message: 'error',\n            nested: {\n              type: 'test',\n              message: 'error',\n              deepNested: {\n                type: 'deepNested',\n                message: 'error',\n              },\n            },\n          },\n        },\n        {},\n        'test1.nested.deepNested.whatever',\n      ),\n    ).toEqual({\n      error: { message: 'error', type: 'deepNested' },\n      name: 'test1.nested.deepNested',\n    });\n  });\n\n  it('should return undefined when not found', () => {\n    expect(\n      schemaErrorLookup(\n        {\n          test: {\n            type: 'test',\n            message: 'error',\n          },\n        },\n        {},\n        'test1234',\n      ),\n    ).toEqual({ error: undefined, name: 'test1234' });\n\n    expect(\n      schemaErrorLookup(\n        {\n          test: {\n            type: 'test',\n            message: 'error',\n          },\n        },\n        {},\n        'testX.1.test',\n      ),\n    ).toEqual({\n      name: 'testX.1.test',\n    });\n\n    expect(\n      schemaErrorLookup<{\n        test: {\n          test: string;\n          test1: string;\n        };\n      }>(\n        {\n          test: {\n            test: {\n              type: 'test',\n              message: 'error',\n            },\n            test1: {\n              type: 'test',\n              message: 'error',\n            },\n          },\n        },\n        {},\n        'test.test2',\n      ),\n    ).toEqual({\n      name: 'test.test2',\n    });\n  });\n\n  it('should prevent error from reported when field is identified', () => {\n    expect(\n      schemaErrorLookup<{\n        test: {\n          test: string;\n          test1: string;\n        };\n      }>(\n        {\n          test: {\n            test: {\n              type: 'test',\n              message: 'error',\n            },\n            test1: {\n              type: 'test',\n              message: 'error',\n            },\n          },\n        },\n        {\n          test: {\n            test1: {\n              _f: {\n                ref: {},\n                name: 'test',\n              },\n            },\n          },\n        },\n        'test.test1.whatever',\n      ),\n    ).toEqual({\n      name: 'test.test1.whatever',\n    });\n\n    expect(\n      schemaErrorLookup<{\n        test: {\n          test: string;\n          test1: string;\n        };\n      }>(\n        {\n          test: {\n            test: {\n              type: 'test',\n              message: 'error',\n            },\n            test1: {\n              type: 'test',\n              message: 'error',\n            },\n          },\n        },\n        {\n          test: {\n            test1: {\n              _f: {\n                ref: {},\n                name: 'test',\n              },\n            },\n          },\n        },\n        'test.testXYZ',\n      ),\n    ).toEqual({\n      name: 'test.testXYZ',\n    });\n  });\n\n  it('should find the nearest root error', () => {\n    const errors = {\n      test: {\n        0: {\n          root: {\n            type: 'root',\n            message: 'higher-root',\n          },\n          nested: {\n            root: {\n              type: 'root',\n              message: 'correct-root',\n            },\n            0: {\n              deepNested: {\n                type: 'deepNested',\n                message: 'error',\n              },\n            },\n          },\n        },\n      },\n    };\n\n    expect(\n      schemaErrorLookup<{ test: { nested: { deepNested: string }[] }[] }>(\n        errors,\n        {},\n        'test.0.nested.1',\n      ),\n    ).toEqual({\n      error: { message: 'correct-root', type: 'root' },\n      name: 'test.0.nested.root',\n    });\n\n    expect(\n      schemaErrorLookup<{ test: { nested: { deepNested: string }[] }[] }>(\n        errors,\n        {},\n        'test.0.nested.0.deepNested',\n      ),\n    ).toEqual({\n      error: { message: 'error', type: 'deepNested' },\n      name: 'test.0.nested.0.deepNested',\n    });\n  });\n\n  it('should not report a nested error container as the exact-name field error', () => {\n    expect(\n      schemaErrorLookup<{ test: { nested: string } }>(\n        {\n          test: {\n            nested: {\n              type: 'nested',\n              message: 'error',\n            },\n          },\n        } as never,\n        {},\n        'test',\n      ),\n    ).toEqual({\n      name: 'test',\n    });\n  });\n\n  it('should resolve an exact-name root error to the .root path', () => {\n    expect(\n      schemaErrorLookup<{ test: string[] }>(\n        {\n          test: {\n            root: {\n              type: 'minLength',\n              message: 'too few',\n            },\n          },\n        } as never,\n        {},\n        'test',\n      ),\n    ).toEqual({\n      error: { type: 'minLength', message: 'too few' },\n      name: 'test.root',\n    });\n  });\n});\n",
      "contentHash": "e0769ed11e156faf5e6c857a4a1f795230b3f519fa60a971586b975a1401e970",
