      "path": "src/__tests__/logic/skipValidation.test.ts",
      "folder": "src/__tests__/logic",
      "content": "import skipValidation from '../../logic/skipValidation';\n\ndescribe('should skip validation', () => {\n  it('when is onChange mode and blur event', () => {\n    expect(\n      skipValidation(\n        false,\n        false,\n        false,\n        {\n          isOnChange: true,\n          isOnBlur: false,\n        },\n        {\n          isOnChange: true,\n          isOnBlur: true,\n          isOnTouch: false,\n        },\n      ),\n    ).toBeTruthy();\n  });\n\n  it('when is onSubmit mode and re-validate on Submit', () => {\n    expect(\n      skipValidation(\n        false,\n        false,\n        false,\n        {\n          isOnChange: false,\n          isOnBlur: false,\n        },\n        {\n          isOnChange: false,\n          isOnBlur: false,\n          isOnTouch: false,\n        },\n      ),\n    ).toBeTruthy();\n  });\n\n  it('when is onSubmit mode and not submitted yet', () => {\n    expect(\n      skipValidation(\n        false,\n        false,\n        false,\n        {\n          isOnChange: true,\n          isOnBlur: false,\n        },\n        {\n          isOnChange: false,\n          isOnBlur: false,\n          isOnTouch: false,\n        },\n      ),\n    ).toBeTruthy();\n  });\n\n  it('when on blur mode, not blur event and error gets clear', () => {\n    expect(\n      skipValidation(\n        false,\n        false,\n        false,\n        {\n          isOnChange: true,\n          isOnBlur: false,\n        },\n        {\n          isOnChange: false,\n          isOnBlur: true,\n          isOnTouch: false,\n        },\n      ),\n    ).toBeTruthy();\n  });\n\n  it('when re-validate mode is blur, not blur event and has error ', () => {\n    expect(\n      skipValidation(\n        false,\n        false,\n        true,\n        {\n          isOnChange: true,\n          isOnBlur: true,\n        },\n        {\n          isOnChange: false,\n          isOnBlur: false,\n          isOnTouch: false,\n        },\n      ),\n    ).toBeTruthy();\n  });\n\n  it('when is re-validate mode on submit and have error', () => {\n    expect(\n      skipValidation(\n        false,\n        false,\n        true,\n        {\n          isOnChange: false,\n          isOnBlur: false,\n        },\n        {\n          isOnChange: false,\n          isOnBlur: false,\n          isOnTouch: false,\n        },\n      ),\n    ).toBeTruthy();\n  });\n});\n\ndescribe('should validate the input', () => {\n  it('when form is submitted and there is error', () => {\n    expect(\n      skipValidation(\n        false,\n        false,\n        true,\n        {\n          isOnChange: true,\n          isOnBlur: false,\n        },\n        {\n          isOnChange: false,\n          isOnBlur: false,\n          isOnTouch: false,\n        },\n      ),\n    ).toBeFalsy();\n  });\n\n  it('when mode is under all', () => {\n    expect(\n      skipValidation(\n        false,\n        false,\n        false,\n        {\n          isOnChange: false,\n          isOnBlur: false,\n        },\n        {\n          isOnChange: false,\n          isOnBlur: false,\n          isOnAll: true,\n        },\n      ),\n    ).toBeFalsy();\n  });\n\n  it('when user blur input and there is no more error', () => {\n    expect(\n      skipValidation(\n        true,\n        false,\n        false,\n        {\n          isOnChange: true,\n          isOnBlur: false,\n        },\n        {\n          isOnChange: false,\n          isOnBlur: true,\n          isOnTouch: false,\n        },\n      ),\n    ).toBeFalsy();\n  });\n\n  it('when user blur and there is an error', () => {\n    expect(\n      skipValidation(\n        true,\n        false,\n        false,\n        {\n          isOnChange: true,\n          isOnBlur: false,\n        },\n        {\n          isOnChange: false,\n          isOnBlur: true,\n          isOnTouch: false,\n        },\n      ),\n    ).toBeFalsy();\n  });\n});\n",
