      "path": "src/__tests__/utils/cloneObject.test.ts",
      "folder": "src/__tests__/utils",
      "content": "import cloneObject from '../../utils/cloneObject';\nimport noop from '../../utils/noop';\n\ndescribe('clone', () => {\n  it('should clone object and not mutate the original object', () => {\n    const fileData = new File([''], 'filename');\n    const data: Record<string, any> = {\n      items: [],\n      test: {\n        date: new Date('2020-10-15'),\n        test0: 12,\n        test1: '12',\n        test2: [1, 2, 3, 4],\n        deep: {\n          date: new Date('2020-10-15'),\n          test0: 12,\n          test1: '12',\n          test2: [\n            1,\n            2,\n            3,\n            4,\n            {\n              file: fileData,\n            },\n          ],\n          file: fileData,\n        },\n      },\n      file: fileData,\n      test2: new Set([1, 2]),\n      test1: new Map([\n        [1, 'one'],\n        [2, 'two'],\n        [3, 'three'],\n      ]),\n    };\n\n    const copy = cloneObject(data);\n    expect(cloneObject(data)).toEqual(copy);\n\n    copy.test.what = '1243';\n    copy.test.date = new Date('2020-10-16');\n    copy.items[0] = 2;\n\n    expect(data).toEqual({\n      items: [],\n      test: {\n        date: new Date('2020-10-15'),\n        test0: 12,\n        test1: '12',\n        test2: [1, 2, 3, 4],\n        deep: {\n          date: new Date('2020-10-15'),\n          test0: 12,\n          test1: '12',\n          test2: [\n            1,\n            2,\n            3,\n            4,\n            {\n              file: fileData,\n            },\n          ],\n          file: fileData,\n        },\n      },\n      file: fileData,\n      test2: new Set([1, 2]),\n      test1: new Map([\n        [1, 'one'],\n        [2, 'two'],\n        [3, 'three'],\n      ]),\n    });\n\n    data.items = [1, 2, 3];\n\n    expect(copy.items).toEqual([2]);\n  });\n\n  it('should skip clone if a node is instance of function', () => {\n    const data = {\n      test: {\n        testFunction: noop,\n        test: 'inner-string',\n        deep: {\n          testFunction: noop,\n          test: 'deep-string',\n        },\n      },\n      testFunction: noop,\n      other: 'string',\n    };\n\n    const copy = cloneObject(data);\n    data.test.deep.test = 'changed-deep-string';\n\n    expect(copy).toEqual({\n      test: {\n        test: 'inner-string',\n        deep: {\n          testFunction: noop,\n          test: 'deep-string',\n        },\n        testFunction: noop,\n      },\n      testFunction: noop,\n      other: 'string',\n    });\n  });\n\n  it('should skip clone if a node is not planeObject', () => {\n    class Foo {\n      a = 1;\n      b = 1;\n\n      static c = function () {};\n    }\n\n    const object = new Foo();\n    const copy = cloneObject(object);\n\n    expect(copy).toBe(object);\n  });\n\n  describe('FileList not defined', () => {\n    const fileList = globalThis.FileList;\n\n    beforeAll(() => {\n      // @ts-expect-error we want to test that clone skips if FileList is not defined.\n      delete globalThis.FileList;\n    });\n\n    afterAll(() => {\n      globalThis.FileList = fileList;\n    });\n\n    it('should skip clone if FileList is not defined', () => {\n      const data = {\n        a: 1,\n        b: 2,\n      };\n      const copy = cloneObject(data);\n\n      expect(copy).toEqual(data);\n    });\n  });\n\n  describe('Blob not a constructor', () => {\n    const blob = globalThis.Blob;\n\n    afterEach(() => {\n      globalThis.Blob = blob;\n    });\n\n    it('should skip clone if Blob is undefined', () => {\n      // @ts-expect-error we want to test that clone skips if Blob is undefined.\n      globalThis.Blob = undefined;\n\n      const data = {\n        a: 1,\n        b: 2,\n      };\n\n      expect(() => cloneObject(data)).not.toThrow();\n      expect(cloneObject(data)).toEqual(data);\n    });\n\n    it('should skip clone if Blob is not defined', () => {\n      // @ts-expect-error we want to test that clone skips if Blob is not defined.\n      delete globalThis.Blob;\n\n      const data = {\n        a: 1,\n        b: 2,\n      };\n\n      expect(() => cloneObject(data)).not.toThrow();\n      expect(cloneObject(data)).toEqual(data);\n    });\n  });\n\n  describe('in presence of Array polyfills', () => {\n    beforeAll(() => {\n      // @ts-expect-error we want to test that clone skips polyfill\n      Array.prototype.somePolyfill = () => 123;\n    });\n\n    it('should skip polyfills while cloning', () => {\n      const data = [1];\n      const copy = cloneObject(data);\n\n      expect(Object.hasOwn(copy, 'somePolyfill')).toBe(false);\n    });\n\n    afterAll(() => {\n      // @ts-expect-error we want to test that clone skips polyfill\n      delete Array.prototype.somePolyfill;\n    });\n  });\n\n  it('should not override prototype of nested object', () => {\n    const UtcProto = {\n      _tag: 'Utc',\n    };\n    const formValues = {\n      dateTime: Object.create(UtcProto),\n    };\n    const copy = cloneObject(formValues);\n    expect(Object.getPrototypeOf(copy.dateTime)).toEqual(UtcProto);\n    expect(copy.dateTime._tag).toBe('Utc');\n  });\n\n  it('should not override prototype of nested object', () => {\n    const UtcProto = {\n      _tag: 'Utc',\n    };\n    const dateTime = Object.create(UtcProto);\n    const copy = cloneObject(dateTime);\n    expect(copy._tag).toBe('Utc');\n  });\n\n  it('should clone object with null prototype', () => {\n    const data = Object.assign(Object.create(null), {\n      name: 'test',\n      nested: Object.assign(Object.create(null), { value: 1 }),\n    });\n    const copy = cloneObject(data);\n\n    expect(copy).not.toBe(data);\n    expect(copy.nested).not.toBe(data.nested);\n    expect(Object.getPrototypeOf(copy)).toBeNull();\n\n    copy.name = 'changed';\n    copy.nested.value = 2;\n\n    expect(data.name).toBe('test');\n    expect(data.nested.value).toBe(1);\n  });\n});\n",
      "contentHash": "a5db8ba5b802f4bb1940abd89f6260994996bd750ef103eb430b679154d77558",
