      "path": "src/__tests__/utils/extractFormValues.test.ts",
      "folder": "src/__tests__/utils",
      "content": "import extractFormValues from '../../utils/extractFormValues';\n\ndescribe('extractFormValues', () => {\n  it('should return extracted form values based on form state', () => {\n    const formData = {\n      test: {\n        test: 'test',\n        test1: 'test1',\n        test2: 'test2',\n        test3: 'test3',\n        test4: {\n          test: 'test',\n          test1: 'test1',\n          test2: 'test2',\n          test3: 'test3',\n        },\n      },\n    };\n\n    const touchedFields = {\n      test: {\n        test: true,\n        test4: {\n          test3: true,\n        },\n      },\n    };\n\n    expect(extractFormValues(touchedFields, formData)).toEqual({\n      test: {\n        test: 'test',\n        test4: {\n          test3: 'test3',\n        },\n      },\n    });\n  });\n\n  it('should only extract the marked entries of a field array', () => {\n    const formData = {\n      records: [\n        { name: 'test', note: 'note' },\n        { name: 'test1', note: 'note1' },\n      ],\n    };\n\n    const dirtyFields = {\n      records: [undefined, { name: true }],\n    };\n\n    expect(extractFormValues(dirtyFields, formData)).toEqual({\n      records: [undefined, { name: 'test1' }],\n    });\n  });\n});\n",
