      "path": "src/__tests__/utils/move.test.ts",
      "folder": "src/__tests__/utils",
      "content": "import move from '../../utils/move';\n\ndescribe('move', () => {\n  it('should be able to move element of array', () => {\n    const data = [\n      {\n        firstName: '1',\n        lastName: 'Luo',\n        id: '75309979-e340-49eb-8016-5f67bfb56c1c',\n      },\n      {\n        firstName: '2',\n        lastName: 'Luo',\n        id: '75309979-e340-49eb-8016-5f67bfb56c1c',\n      },\n      {\n        firstName: '3',\n        lastName: 'Luo',\n        id: '75309979-e340-49eb-8016-5f67bfb56c1c',\n      },\n    ];\n    move(data, 0, 2);\n    expect(data).toEqual([\n      {\n        firstName: '2',\n        lastName: 'Luo',\n        id: '75309979-e340-49eb-8016-5f67bfb56c1c',\n      },\n      {\n        firstName: '3',\n        lastName: 'Luo',\n        id: '75309979-e340-49eb-8016-5f67bfb56c1c',\n      },\n      {\n        firstName: '1',\n        lastName: 'Luo',\n        id: '75309979-e340-49eb-8016-5f67bfb56c1c',\n      },\n    ]);\n  });\n\n  it('should be able to move element backward in the array', () => {\n    const data = ['a', 'b', 'c'];\n    move(data, 2, 0);\n    expect(data).toEqual(['c', 'a', 'b']);\n  });\n\n  it('should be a no-op when moving an index to itself', () => {\n    const data = ['a', 'b', 'c'];\n    move(data, 1, 1);\n    expect(data).toEqual(['a', 'b', 'c']);\n  });\n\n  it('should return empty array when data passed was not an array', () => {\n    // @ts-expect-error we want to test function on non-array input\n    expect(move({}, 0, 3)).toEqual([]);\n  });\n\n  it('should move nested item with empty slot', () => {\n    expect(move([{ subFields: [{ test: '1' }] }], 0, 1)).toEqual([\n      undefined,\n      { subFields: [{ test: '1' }] },\n    ]);\n\n    expect(move([{ subFields: [{ test: '1' }] }], 0, 2)).toEqual([\n      undefined,\n      undefined,\n      { subFields: [{ test: '1' }] },\n    ]);\n  });\n});\n",
