      "path": "src/__tests__/watch.server.test.tsx",
      "folder": "src/__tests__",
      "content": "import React from 'react';\nimport { renderToString } from 'react-dom/server';\n\nimport { useForm } from '../useForm';\nimport { Watch } from '../watch';\n\ndescribe('Watch with SSR', () => {\n  it('should be rendered correctly', () => {\n    const Component = () => {\n      const { control } = useForm({ defaultValues: { foo: 'bar' } });\n      return (\n        <Watch\n          control={control}\n          names={['foo']}\n          render={([foo]) => <span>{foo}</span>}\n        />\n      );\n    };\n\n    expect(renderToString(<Component />)).toBe('<span>bar</span>');\n  });\n});\n",
      "contentHash": "42b04533021e169e564856f8315b1d71564af0691d71d15f6ccc4782758a7781",
