      "path": "src/logic/appendErrors.ts",
      "folder": "src/logic",
      "content": "import type {\n  InternalFieldErrors,\n  InternalFieldName,\n  ValidateResult,\n} from '../types';\n\nexport default (\n  name: InternalFieldName,\n  validateAllFieldCriteria: boolean,\n  errors: InternalFieldErrors,\n  type: string,\n  message: ValidateResult,\n) =>\n  validateAllFieldCriteria\n    ? {\n        ...errors[name],\n        types: {\n          ...(errors[name] && errors[name]!.types ? errors[name]!.types : {}),\n          [type]: message || true,\n        },\n      }\n    : {};\n",
      "contentHash": "e0d63668af281bf3dcea91635423639301a9df5a9cb36463c24d6c15084d11e1",
      "lineCount": 23,
      "moduleKind": "esm",
