      "path": "src/logic/unsetEmptyArray.ts",
      "folder": "src/logic",
      "content": "import compact from '../utils/compact';\nimport get from '../utils/get';\nimport unset from '../utils/unset';\n\nexport default <T>(ref: T, name: string) => {\n  const array = get(ref, name);\n\n  !compact(array).length &&\n    !(array && (array as { root?: unknown }).root) &&\n    unset(ref, name);\n};\n",
      "contentHash": "18be3d2691346124537bd72fbe59c0911cb8ff449bc0c6cef7b4f814a6c8dd31",
      "lineCount": 12,
      "moduleKind": "esm",
