      "path": "src/types/path/eager.ts",
      "folder": "src/types/path",
      "content": "import type { FieldValues } from '../fields';\nimport type {\n  BrowserNativeObject,\n  IsAny,\n  IsEqual,\n  OpaqueType,\n  Primitive,\n} from '../utils';\n\nimport type { ArrayKey, IsTuple, Prev, TupleKeys } from './common';\n\n/**\n * Helper function to break apart T1 and check if any are equal to T2\n *\n * See {@link IsEqual}\n */\ntype AnyIsEqual<T1, T2> = T1 extends T2\n  ? IsEqual<T1, T2> extends true\n    ? true\n    : never\n  : never;\n\n/**\n * Helper type for recursively constructing paths through a type.\n * This actually constructs the strings and recurses into nested\n * object types.\n *\n * See {@link Path}\n */\ntype PathImpl<\n  K extends string | number,\n  V,\n  TraversedTypes,\n  D extends number = 9,\n> = V extends Primitive | BrowserNativeObject | OpaqueType\n  ? `${K}`\n  : // Check so that we don't recurse into the same type\n    // by ensuring that the types are mutually assignable\n    // mutually required to avoid false positives of subtypes\n    true extends AnyIsEqual<TraversedTypes, V>\n    ? `${K}`\n    : `${K}` | `${K}.${PathInternal<V, TraversedTypes | V, Prev[D]>}`;\n\n/**\n * Helper type for recursively constructing paths through a type.\n * This obscures the internal type param TraversedTypes from exported contract.\n *\n * See {@link Path}\n */\ntype PathInternal<T, TraversedTypes = T, D extends number = 9> = [D] extends [\n  never,\n]\n  ? never\n  : T extends ReadonlyArray<infer V>\n    ? IsTuple<T> extends true\n      ? {\n          [K in TupleKeys<T>]-?: PathImpl<K & string, T[K], TraversedTypes, D>;\n        }[TupleKeys<T>]\n      : PathImpl<ArrayKey, V, TraversedTypes, D>\n    : {\n        [K in keyof T]-?: PathImpl<K & string, T[K], TraversedTypes, D>;\n      }[keyof T];\n\n/**\n * Type which eagerly collects all paths through a type\n * @typeParam T - type which should be introspected\n * @example\n * ```\n * Path<{foo: {bar: string}}> = 'foo' | 'foo.bar'\n * ```\n */\n// We want to explode the union type and process each individually\n// so assignable types don't leak onto the stack from the base.\nexport type Path<T> = T extends any ? PathInternal<T> : never;\n\n/**\n * See {@link Path}\n */\nexport type FieldPath<TFieldValues extends FieldValues> = Path<TFieldValues>;\n\n/**\n * Helper type for recursively constructing paths through a type.\n * This actually constructs the strings and recurses into nested\n * object types.\n *\n * See {@link ArrayPath}\n */\ntype ArrayPathImpl<\n  K extends string | number,\n  V,\n  TraversedTypes,\n  D extends number = 9,\n> = V extends Primitive | BrowserNativeObject | OpaqueType\n  ? IsAny<V> extends true\n    ? string\n    : never\n  : V extends ReadonlyArray<infer U>\n    ? U extends Primitive | BrowserNativeObject | OpaqueType\n      ? IsAny<V> extends true\n        ? string\n        : never\n      : // Check so that we don't recurse into the same type\n        // by ensuring that the types are mutually assignable\n        // mutually required to avoid false positives of subtypes\n        true extends AnyIsEqual<TraversedTypes, V>\n        ? never\n        : `${K}` | `${K}.${ArrayPathInternal<V, TraversedTypes | V, Prev[D]>}`\n    : true extends AnyIsEqual<TraversedTypes, V>\n      ? never\n      : `${K}.${ArrayPathInternal<V, TraversedTypes | V, Prev[D]>}`;\n\n/**\n * Helper type for recursively constructing paths through a type.\n * This obscures the internal type param TraversedTypes from exported contract.\n *\n * See {@link ArrayPath}\n */\ntype ArrayPathInternal<T, TraversedTypes = T, D extends number = 9> = [\n  D,\n] extends [never]\n  ? never\n  : T extends ReadonlyArray<infer V>\n    ? IsTuple<T> extends true\n      ? {\n          [K in TupleKeys<T>]-?: ArrayPathImpl<\n            K & string,\n            T[K],\n            TraversedTypes,\n            D\n          >;\n        }[TupleKeys<T>]\n      : ArrayPathImpl<ArrayKey, V, TraversedTypes, D>\n    : {\n        [K in keyof T]-?: ArrayPathImpl<K & string, T[K], TraversedTypes, D>;\n      }[keyof T];\n\n/**\n * Type which eagerly collects all paths through a type which point to an array\n * type.\n * @typeParam T - type which should be introspected.\n * @example\n * ```\n * Path<{foo: {bar: string[], baz: number[]}}> = 'foo.bar' | 'foo.baz'\n * ```\n */\n// We want to explode the union type and process each individually\n// so assignable types don't leak onto the stack from the base.\nexport type ArrayPath<T> = T extends any ? ArrayPathInternal<T> : never;\n\n/**\n * See {@link ArrayPath}\n */\nexport type FieldArrayPath<TFieldValues extends FieldValues> =\n  ArrayPath<TFieldValues>;\n\n/**\n * Type to evaluate the type which the given path points to.\n * @typeParam T - deeply nested type which is indexed by the path\n * @typeParam P - path into the deeply nested type\n * @example\n * ```\n * PathValue<{foo: {bar: string}}, 'foo.bar'> = string\n * PathValue<[number, string], '1'> = string\n * ```\n */\nexport type PathValue<T, P extends Path<T> | ArrayPath<T>> = PathValueImpl<\n  T,\n  P\n>;\n\ntype PathValueImpl<T, P extends string> = T extends any\n  ? P extends `${infer K}.${infer R}`\n    ? K extends keyof T\n      ? undefined extends T[K]\n        ? PathValueImpl<T[K], R> | undefined\n        : PathValueImpl<T[K], R>\n      : K extends `${ArrayKey}`\n        ? T extends ReadonlyArray<infer V>\n          ? PathValueImpl<V, R>\n          : never\n        : never\n    : P extends keyof T\n      ? T[P]\n      : P extends `${ArrayKey}`\n        ? T extends ReadonlyArray<infer V>\n          ? V\n          : T extends undefined\n            ? undefined\n            : never\n        : never\n  : never;\n\n/**\n * See {@link PathValue}\n */\nexport type FieldPathValue<\n  TFieldValues extends FieldValues,\n  TFieldPath extends FieldPath<TFieldValues>,\n> = PathValue<TFieldValues, TFieldPath>;\n\n/**\n * See {@link PathValue}\n */\nexport type FieldArrayPathValue<\n  TFieldValues extends FieldValues,\n  TFieldArrayPath extends FieldArrayPath<TFieldValues>,\n> = PathValue<TFieldValues, TFieldArrayPath>;\n\n/**\n * Type to evaluate the type which the given paths point to.\n * @typeParam TFieldValues - field values which are indexed by the paths\n * @typeParam TPath        - paths into the deeply nested field values\n * @example\n * ```\n * FieldPathValues<{foo: {bar: string}}, ['foo', 'foo.bar']>\n *   = [{bar: string}, string]\n * ```\n */\nexport type FieldPathValues<\n  TFieldValues extends FieldValues,\n  TPath extends FieldPath<TFieldValues>[] | readonly FieldPath<TFieldValues>[],\n> = {} & {\n  [K in keyof TPath]: FieldPathValue<\n    TFieldValues,\n    TPath[K] & FieldPath<TFieldValues>\n  >;\n};\n\n/**\n * Type which eagerly collects all paths through a fieldType that matches a give type\n * @typeParam TFieldValues - field values which are indexed by the paths\n * @typeParam TValue       - the value you want to match into each type\n * @example\n * ```typescript\n * FieldPathByValue<{foo: {bar: number}, baz: number, bar: string}, number>\n *   = 'foo.bar' | 'baz'\n * ```\n */\nexport type FieldPathByValue<TFieldValues extends FieldValues, TValue> = {\n  [Key in FieldPath<TFieldValues>]: FieldPathValue<\n    TFieldValues,\n    Key\n  > extends TValue\n    ? Key\n    : never;\n}[FieldPath<TFieldValues>];\n\n/**\n * Type which eagerly collects all array paths through a fieldType that matches a give type\n * @typeParam TFieldValues - field values which are indexed by the paths\n * @typeParam TValue       - the value you want to match into each type\n * @example\n * ```typescript\n * FieldArrayPathByValue<{foo: {bar: number}[], baz: number, bar: string}, {bar: number}[]>\n *   = 'foo'\n * ```\n */\nexport type FieldArrayPathByValue<TFieldValues extends FieldValues, TValue> = {\n  [Key in FieldArrayPath<TFieldValues>]: FieldArrayPathValue<\n    TFieldValues,\n    Key\n  > extends TValue\n    ? Key\n    : never;\n}[FieldArrayPath<TFieldValues>];\n",
