      "path": "src/useController.ts",
      "folder": "src",
      "content": "import React from 'react';\n\nimport getEventValue from './logic/getEventValue';\nimport getNullAncestorValue from './logic/getNullAncestorValue';\nimport isNameInFieldArray from './logic/isNameInFieldArray';\nimport cloneObject from './utils/cloneObject';\nimport get from './utils/get';\nimport isBoolean from './utils/isBoolean';\nimport isFunction from './utils/isFunction';\nimport isUndefined from './utils/isUndefined';\nimport set from './utils/set';\nimport { EVENTS } from './constants';\nimport type {\n  ControllerFieldState,\n  Field,\n  FieldPath,\n  FieldPathValue,\n  FieldValues,\n  InternalFieldName,\n  UseControllerProps,\n  UseControllerReturn,\n} from './types';\nimport { useFormControlContext } from './useFormControlContext';\nimport { useFormState } from './useFormState';\nimport { useWatch } from './useWatch';\n\n/**\n * Hook for controlled inputs. Returns `field`, `fieldState`, and `formState`.\n * Re-renders are isolated to the hook level.\n *\n * @see [API](https://react-hook-form.com/docs/usecontroller)\n *\n * @example\n * ```tsx\n * const { field, fieldState } = useController({ control, name: \"email\" });\n * return <input {...field} />;\n * ```\n */\nexport function useController<\n  TFieldValues extends FieldValues = FieldValues,\n  TName extends FieldPath<TFieldValues> = FieldPath<TFieldValues>,\n  TTransformedValues = TFieldValues,\n>(\n  props: UseControllerProps<TFieldValues, TName, TTransformedValues>,\n): UseControllerReturn<TFieldValues, TName> {\n  const formControl = useFormControlContext<\n    TFieldValues,\n    unknown,\n    TTransformedValues\n  >();\n  const {\n    name,\n    disabled,\n    control = formControl,\n    shouldUnregister,\n    defaultValue,\n    exact = true,\n  } = props;\n  const isArrayField = isNameInFieldArray(control._names.array, name);\n\n  const defaultValueMemo = React.useMemo(() => {\n    const resolved = get(\n      control._formValues,\n      name,\n      get(control._defaultValues, name, defaultValue),\n    );\n\n    return isUndefined(resolved)\n      ? getNullAncestorValue(control, name)\n      : resolved;\n  }, [control, name, defaultValue]);\n\n  const value = useWatch({\n    control,\n    name,\n    defaultValue: defaultValueMemo,\n    exact,\n  }) as FieldPathValue<TFieldValues, TName>;\n\n  const formState = useFormState({\n    control,\n    name,\n    exact,\n  });\n\n  const _props = React.useRef(props);\n  const _proxyRef = React.useRef<any>(null);\n\n  const _registerProps = React.useRef(\n    control.register(name, {\n      ...props.rules,\n      value,\n      ...(isBoolean(props.disabled) ? { disabled: props.disabled } : {}),\n    }),\n  );\n\n  _props.current = props;\n\n  const fieldState = React.useMemo(\n    () =>\n      Object.defineProperties(\n        {},\n        {\n          invalid: {\n            enumerable: true,\n            get: () => !!get(formState.errors, name),\n          },\n          isDirty: {\n            enumerable: true,\n            get: () => !!get(formState.dirtyFields, name),\n          },\n          isTouched: {\n            enumerable: true,\n            get: () => !!get(formState.touchedFields, name),\n          },\n          isValidating: {\n            enumerable: true,\n            get: () => !!get(formState.validatingFields, name),\n          },\n          error: {\n            enumerable: true,\n            get: () => get(formState.errors, name),\n          },\n        },\n      ) as ControllerFieldState,\n    [formState, name],\n  );\n\n  const onChange = React.useCallback(\n    (event: unknown) => {\n      const value = getEventValue(event);\n\n      if (!get(control._fields, name)) {\n        _registerProps.current = control.register(name, {\n          ..._props.current.rules,\n          value,\n        });\n      }\n\n      return _registerProps.current.onChange({\n        target: {\n          value: getEventValue(event),\n          name: name as InternalFieldName,\n        },\n        type: EVENTS.CHANGE,\n      });\n    },\n    [name, control],\n  );\n\n  const onBlur = React.useCallback(() => {\n    const value = get(control._formValues, name);\n\n    if (!get(control._fields, name)) {\n      _registerProps.current = control.register(name, {\n        ..._props.current.rules,\n        value,\n      });\n    }\n\n    return _registerProps.current.onBlur({\n      target: {\n        value,\n        name: name as InternalFieldName,\n      },\n      type: EVENTS.BLUR,\n    });\n  }, [name, control]);\n\n  const ref = React.useCallback(\n    (elm: any) => {\n      if (elm) {\n        _proxyRef.current = {\n          focus: () => isFunction(elm.focus) && elm.focus(),\n          select: () => isFunction(elm.select) && elm.select(),\n          setCustomValidity: (message: string) =>\n            isFunction(elm.setCustomValidity) && elm.setCustomValidity(message),\n          reportValidity: () =>\n            isFunction(elm.reportValidity) && elm.reportValidity(),\n        };\n      }\n\n      const field = get(control._fields, name);\n\n      if (field && field._f && elm) {\n        field._f.ref = _proxyRef.current;\n        field._f._c = true;\n      }\n    },\n    [control._fields, name],\n  );\n\n  const field = React.useMemo(\n    () => ({\n      name,\n      value,\n      ...(isBoolean(disabled) || formState.disabled\n        ? { disabled: formState.disabled || disabled }\n        : {}),\n      onChange,\n      onBlur,\n      ref,\n    }),\n    [name, disabled, formState.disabled, onChange, onBlur, ref, value],\n  );\n\n  React.useEffect(() => {\n    const _shouldUnregisterField =\n      control._options.shouldUnregister || shouldUnregister;\n\n    _registerProps.current = control.register(name, {\n      ..._props.current.rules,\n      ...(isBoolean(_props.current.disabled)\n        ? { disabled: _props.current.disabled }\n        : {}),\n    });\n\n    const updateMounted = (name: InternalFieldName, value: boolean) => {\n      const field: Field = get(control._fields, name);\n\n      if (field && field._f) {\n        field._f.mount = value;\n        field._f._c = value;\n      }\n    };\n\n    updateMounted(name, true);\n\n    if (_shouldUnregisterField) {\n      const value = cloneObject(\n        get(\n          shouldUnregister\n            ? control._defaultValues\n            : control._options.values || control._defaultValues,\n          name,\n          get(\n            control._options.defaultValues,\n            name,\n            _props.current.defaultValue,\n          ),\n        ),\n      );\n      set(control._defaultValues, name, value);\n      if (isUndefined(get(control._formValues, name))) {\n        set(control._formValues, name, value);\n      }\n    }\n\n    !isArrayField &&\n      control.register(name, {\n        ..._props.current.rules,\n        ...(isBoolean(_props.current.disabled)\n          ? { disabled: _props.current.disabled }\n          : {}),\n      });\n\n    if (_proxyRef.current) {\n      const field: Field = get(control._fields, name);\n      if (field && field._f) {\n        field._f.ref = _proxyRef.current;\n      }\n    }\n\n    return () => {\n      (\n        isArrayField\n          ? _shouldUnregisterField && !control._state.action\n          : _shouldUnregisterField\n      )\n        ? control.unregister(name)\n        : updateMounted(name, false);\n    };\n  }, [name, control, isArrayField, shouldUnregister]);\n\n  React.useEffect(() => {\n    control._setDisabledField({\n      disabled,\n      name,\n    });\n  }, [disabled, name, control]);\n\n  return React.useMemo(\n    () => ({\n      field,\n      formState,\n      fieldState,\n    }),\n    [field, formState, fieldState],\n  );\n}\n",
      "contentHash": "12bc0f3b8ba34bd87c2576e60185219b537b7823984070f3f4fcb62743095c50",
