      "path": "src/useFormContext.tsx",
      "folder": "src",
      "content": "import React from 'react';\n\nimport type {\n  Control,\n  FieldValues,\n  FormProviderProps,\n  UseFormReturn,\n} from './types';\nimport { HookFormControlContext } from './useFormControlContext';\n\nconst HookFormContext = React.createContext<UseFormReturn | null>(null);\nHookFormContext.displayName = 'HookFormContext';\n\n/**\n * Retrieves all `useForm` methods from the nearest `FormProvider`.\n * Use in deeply nested components to avoid prop-drilling.\n *\n * @see [API](https://react-hook-form.com/docs/useformcontext)\n *\n * @example\n * ```tsx\n * const { register } = useFormContext<FormValues>();\n * ```\n */\nexport const useFormContext = <\n  TFieldValues extends FieldValues,\n  TContext = any,\n  TTransformedValues = TFieldValues,\n>(): UseFormReturn<TFieldValues, TContext, TTransformedValues> =>\n  React.useContext(HookFormContext) as UseFormReturn<\n    TFieldValues,\n    TContext,\n    TTransformedValues\n  >;\n\n/**\n * Provides all `useForm` methods to the component tree via React Context.\n * Pair with `useFormContext` to consume them in any descendant.\n *\n * @see [API](https://react-hook-form.com/docs/useformcontext)\n *\n * @example\n * ```tsx\n * <FormProvider {...methods}>\n *   <form onSubmit={methods.handleSubmit(onSubmit)}>{children}</form>\n * </FormProvider>\n * ```\n */\nexport const FormProvider = <\n  TFieldValues extends FieldValues,\n  TContext = any,\n  TTransformedValues = TFieldValues,\n>({\n  children,\n  watch,\n  getValues,\n  getErrors,\n  getFieldState,\n  setError,\n  clearErrors,\n  setValue,\n  setValues,\n  trigger,\n  formState,\n  resetField,\n  reset,\n  resetDefaultValues,\n  handleSubmit,\n  unregister,\n  control,\n  register,\n  setFocus,\n  subscribe,\n}: FormProviderProps<TFieldValues, TContext, TTransformedValues>) => {\n  const memoizedValue = React.useMemo<\n    UseFormReturn<TFieldValues, TContext, TTransformedValues>\n  >(\n    () => ({\n      watch,\n      getValues,\n      getErrors,\n      getFieldState,\n      setError,\n      clearErrors,\n      setValue,\n      setValues,\n      trigger,\n      formState,\n      resetField,\n      reset,\n      resetDefaultValues,\n      handleSubmit,\n      unregister,\n      control,\n      register,\n      setFocus,\n      subscribe,\n    }),\n    [\n      clearErrors,\n      control,\n      formState,\n      getErrors,\n      getFieldState,\n      getValues,\n      handleSubmit,\n      register,\n      reset,\n      resetDefaultValues,\n      resetField,\n      setError,\n      setFocus,\n      setValue,\n      setValues,\n      subscribe,\n      trigger,\n      unregister,\n      watch,\n    ],\n  );\n\n  return (\n    <HookFormContext.Provider value={memoizedValue as unknown as UseFormReturn}>\n      <HookFormControlContext.Provider value={memoizedValue.control as Control}>\n        {children}\n      </HookFormControlContext.Provider>\n    </HookFormContext.Provider>\n  );\n};\n",
