      "path": "src/utils/cloneObject.ts",
      "folder": "src/utils",
      "content": "import isWeb from './isWeb';\n\nexport default function cloneObject<T>(data: T): T {\n  if (data === null || typeof data !== 'object') {\n    return data;\n  }\n\n  if (data instanceof Date) {\n    return new Date(data) as T;\n  }\n\n  const isBlobInstance = typeof Blob !== 'undefined' && data instanceof Blob;\n  const isFileListInstance =\n    typeof FileList !== 'undefined' && data instanceof FileList;\n\n  if (isWeb && (isBlobInstance || isFileListInstance)) {\n    return data;\n  }\n\n  const isArray = Array.isArray(data);\n  const prototype = Object.getPrototypeOf(data);\n\n  if (!isArray && prototype && (data as object).constructor !== Object) {\n    return data;\n  }\n\n  const copy = isArray ? [] : Object.create(prototype);\n\n  for (const key in data) {\n    if (Object.prototype.hasOwnProperty.call(data, key)) {\n      copy[key] = cloneObject(data[key]);\n    }\n  }\n\n  return copy;\n}\n",
