      "path": "src/utils/createSubject.ts",
      "folder": "src/utils",
      "content": "import type { Noop } from '../types';\n\nexport type Observer<T> = {\n  next: (value: T) => void;\n};\n\nexport type Subscription = {\n  unsubscribe: Noop;\n};\n\nexport type Subject<T> = {\n  readonly observers: Observer<T>[];\n  subscribe: (value: Observer<T>) => Subscription;\n  unsubscribe: Noop;\n} & Observer<T>;\n\nexport default <T>(): Subject<T> => {\n  let _observers = new Set<Observer<T>>();\n  let _iterationCount = 0;\n\n  const next = (value: T) => {\n    const observers = _observers;\n\n    _iterationCount++;\n\n    for (const observer of observers) {\n      observer.next && observer.next(value);\n    }\n\n    observers === _observers && _iterationCount--;\n  };\n\n  const subscribe = (observer: Observer<T>): Subscription => {\n    _observers.add(observer);\n\n    return {\n      unsubscribe: () => {\n        if (_iterationCount) {\n          _observers = new Set(_observers);\n          _iterationCount = 0;\n        }\n\n        _observers.delete(observer);\n      },\n    };\n  };\n\n  const unsubscribe = () => {\n    _observers = new Set();\n    _iterationCount = 0;\n  };\n\n  return {\n    get observers() {\n      return Array.from(_observers);\n    },\n    next,\n    subscribe,\n    unsubscribe,\n  };\n};\n",
