      "path": "src/utils/unset.ts",
      "folder": "src/utils",
      "content": "import { PROTOTYPE_KEYWORDS } from '../constants';\n\nimport isEmptyObject from './isEmptyObject';\nimport isKey from './isKey';\nimport isNullOrUndefined from './isNullOrUndefined';\nimport isObject from './isObject';\nimport isString from './isString';\nimport isUndefined from './isUndefined';\nimport stringToPath from './stringToPath';\n\nfunction baseGet(object: any, updatePath: (string | number)[]) {\n  const length = updatePath.length - 1;\n  let index = 0;\n\n  while (index < length) {\n    if (isNullOrUndefined(object)) {\n      object = undefined;\n      break;\n    }\n    object = object[updatePath[index]];\n    index++;\n  }\n\n  return object;\n}\n\nfunction isEmptyArray(obj: unknown[]) {\n  for (const key in obj) {\n    if (obj.hasOwnProperty(key) && !isUndefined(obj[key])) {\n      return false;\n    }\n  }\n  return true;\n}\n\nexport default function unset(object: any, path: string | (string | number)[]) {\n  if (isString(path) && Object.prototype.hasOwnProperty.call(object, path)) {\n    delete object[path];\n    return object;\n  }\n\n  const paths = Array.isArray(path)\n    ? path\n    : isKey(path)\n      ? [path]\n      : stringToPath(path);\n  if (paths.some((segment) => PROTOTYPE_KEYWORDS.includes(String(segment)))) {\n    return object;\n  }\n  const childObject = paths.length === 1 ? object : baseGet(object, paths);\n\n  const index = paths.length - 1;\n  const key = paths[index];\n\n  if (childObject) {\n    delete childObject[key];\n  }\n\n  if (\n    index !== 0 &&\n    ((isObject(childObject) && isEmptyObject(childObject)) ||\n      (Array.isArray(childObject) && isEmptyArray(childObject)))\n  ) {\n    unset(object, paths.slice(0, -1));\n  }\n\n  return object;\n}\n",
