      "content": "import type {\n  FieldPath,\n  FieldValues,\n  WatchProps,\n  WatchRenderValue,\n} from './types';\nimport { useWatch } from './useWatch';\n\n/**\n * Component wrapper around `useWatch`. Re-renders only when watched fields change.\n *\n * @see [API](https://react-hook-form.com/docs/usewatch)\n *\n * @example\n * ```tsx\n * <Watch\n *   control={control}\n *   names={[\"foo\", \"bar\"]}\n *   render={([foo, bar]) => <span>{foo} {bar}</span>}\n * />\n * ```\n */\nexport const Watch = <\n  TFieldValues extends FieldValues = FieldValues,\n  TFieldName extends\n    | FieldPath<TFieldValues>\n    | readonly [FieldPath<TFieldValues>, ...FieldPath<TFieldValues>[]]\n    | FieldPath<TFieldValues>[]\n    | readonly FieldPath<TFieldValues>[]\n    | undefined = undefined,\n  TContext = any,\n  TTransformedValues = TFieldValues,\n  TComputeValue = undefined,\n>(\n  props: WatchProps<\n    TFieldName,\n    TFieldValues,\n    TContext,\n    TTransformedValues,\n    TComputeValue\n  >,\n) =>\n  props.render(\n    useWatch({ name: props.names, ...(props as any) }) as WatchRenderValue<\n      TFieldName,\n      TFieldValues,\n      TComputeValue\n    >,\n  );\n",
